"""NetconfClientWrapper module"""

from netconf_client.ncclient import Manager as NetconfClientManager
from lxml import etree
from netconf_client.rpc import make_rpc
from taf.ul.oran_mplane.core.libraries.base import LibrariesBase


class NetconfClientWrapper(LibrariesBase):
    """NetconfClientWrapper Class"""

    def __init__(self, manager: NetconfClientManager):
        super().__init__(manager)
        self.manager = manager

    @staticmethod
    def _pretty_xml_from_object(xml_object):
        """
        :param xml_object:
        :return:
        """
        if xml_object:
            return etree.tostring(etree.fromstring(xml_object.data_xml), pretty_print=True).decode()
        return xml_object

    @staticmethod
    def _pretty_xml_from_str(xml_str):
        """
        :param xml_str:
        :return:
        """
        if xml_str:
            return etree.tostring(etree.fromstring(xml_str), pretty_print=True).decode()
        return xml_str

    @staticmethod
    def _pretty_xml_from_etree(etree_element):
        """
        :param etree_element:
        :return:
        """
        if etree_element is not None:
            return etree.tostring(etree_element, pretty_print=True).decode()
        return etree_element

    def get_without_filter(self, with_defaults):
        """
        :param with_defaults:
        :return:
        """
        return self._pretty_xml_from_object(self.manager.get(with_defaults=with_defaults))

    def edit_config(self, request, target, default_operation, test_option, error_option, msg_format):
        """
        :param request:
        :param target:
        :param default_operation:
        :param test_option:
        :param error_option:
        :param msg_format:
        :return:
        """
        return self._pretty_xml_from_str(
            self.manager.edit_config(
                config=request,
                target=target,
                default_operation=default_operation,
                test_option=test_option,
                error_option=error_option,
                format=msg_format,
            )
        )

    def get_xpath(self, msg_filter, with_defaults):
        """
        :param msg_filter:
        :param with_defaults:
        :return:
        """
        return self._pretty_xml_from_object(self.manager.get(msg_filter, with_defaults=with_defaults))

    def get_subtree(self, content, with_defaults):
        """
        :param content:
        :param with_defaults:
        :return:
        """
        return self._pretty_xml_from_object(
            self.manager.get(filter=("subtree", content), with_defaults=with_defaults)
        )

    def create_subscription(self, noti_filter, stream_name, start_time, stop_time):
        """
        :param noti_filter:
        :param stream_name:
        :param start_time:
        :param stop_time:
        :return:
        """
        return self._pretty_xml_from_object(
            self.manager.create_subscription(
                filter=noti_filter, stream=stream_name, start_time=start_time, stop_time=stop_time
            )
        )

    def take_notification(self):
        """
        :return:
        """
        notif = self.manager.take_notification(block=False, timeout=None)
        if notif:
            notif.notification_xml = notif.notification_xml.decode("utf-8")
        return notif

    def get_config(self, source):
        """
        :param source:
        :return:
        """
        return self._pretty_xml_from_object(self.manager.get_config(source))

    def server_capabilities(self):
        """
        :return:
        """
        return list(self.manager.session.server_capabilities)

    def client_capabilities(self):
        """
        :return:
        """
        return list(self.manager.session.client_capabilities)

    def send_rpc(self, msg):
        """
        :param msg:
        :return:
        """
        rpc_msg = make_rpc(etree.tostring(msg).decode())
        (_, etree_element) = self.manager._send_rpc(rpc_msg)
        return self._pretty_xml_from_etree(etree_element)

    def get_session_id(self, *_, **kwargs) -> int:
        """
        Returns session id
        :return: int, session id
        """
        return self.manager.session_id

    def kill_session(self, session_id):
        """
        Kills specified session
        :param session_id:
        :return:
        """
        return self.manager.kill_session(session_id=session_id)
